-- Dumping structure for function gopettae_gopet_web.ComputeSha256Hash
DELIMITER //
CREATE FUNCTION `ComputeSha256Hash`(`Text` VARCHAR(255)) RETURNS varchar(64) CHARSET utf8mb4 COLLATE utf8mb4_general_ci
    DETERMINISTIC
BEGIN
    DECLARE ReversedText VARCHAR(255) DEFAULT '';
    DECLARE i INT;

    -- Đảo ngược chuỗi
    SET i = CHAR_LENGTH(Text);
    WHILE i > 0 DO
        SET ReversedText = CONCAT(ReversedText, SUBSTRING(Text, i, 1));
        SET i = i - 1;
    END WHILE;

    -- Kết hợp chuỗi "goPet", ReversedText và "________"
    SET ReversedText = CONCAT('goPet', ReversedText, '________');

    -- Tính SHA256 và trả về kết quả ở dạng chuỗi hexa
    RETURN LOWER(SHA2(ReversedText, 256));
END//
DELIMITER ;

